	Contract ThirdPartyServices::sendNotificationEmail(email: String) : Boolean {

		/*
		 * Generated by RM2DOc - Precondition
		 * The email is not equal to null
		 */
		precondition:
			email <> ""

		/*
		 * Generated by RM2DOc - Postcondition
		 * The return value was true
		 */
		postcondition:
			result = true

	}

